import React, { useState } from "react";
import { BrowserRouter as Router, Route, Routes, Link } from "react-router-dom";
import "./styles.css";

// Home Page Component
const HomePage = () => {
  return (
    <div className="homePage">
      <h1 className="heading">Welcome to Binance Clone</h1>
      <Link to="/login">
        <button className="button">Get Started</button>
      </Link>
    </div>
  );
};

// Login Page Component
const LoginPage = () => {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");

  const handleLogin = () => {
    // Add login logic here
    console.log("Logging in with:", username, password);
  };

  return (
    <div className="loginPage">
      <h2 className="heading">Login</h2>
      <input
        type="text"
        placeholder="Username"
        value={username}
        onChange={(e) => setUsername(e.target.value)}
        className="input"
      />
      <input
        type="password"
        placeholder="Password"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
        className="input"
      />
      <button onClick={handleLogin} className="button">
        Login
      </button>
      <p className="linkText">
        <Link to="/forgot-password" className="link">
          Forgot Password?
        </Link>
      </p>
      <p className="linkText">
        Don't have an account?{" "}
        <Link to="/signup" className="link">
          Sign Up
        </Link>
      </p>
    </div>
  );
};

// Signup Page Component
const SignupPage = () => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [phone, setPhone] = useState("");

  const handleSignup = () => {
    // Add signup logic here
    console.log("Signing up with:", email, password, phone);
  };

  return (
    <div className="signupPage">
      <h2 className="heading">Sign Up</h2>
      <input
        type="email"
        placeholder="Email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        className="input"
      />
      <input
        type="password"
        placeholder="Password"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
        className="input"
      />
      <input
        type="text"
        placeholder="Phone Number (Optional)"
        value={phone}
        onChange={(e) => setPhone(e.target.value)}
        className="input"
      />
      <button onClick={handleSignup} className="button">
        Sign Up
      </button>
      <p className="linkText">
        Already have an account?{" "}
        <Link to="/login" className="link">
          Login
        </Link>
      </p>
    </div>
  );
};

// KYC Form Component
const KYCForm = () => {
  const [name, setName] = useState("");
  const [phoneNumber, setPhoneNumber] = useState("");
  const [documentType, setDocumentType] = useState("passport");
  const [picture, setPicture] = useState(null);

  const handleSubmit = () => {
    // Add KYC submission logic here
    console.log("Submitting KYC with:", {
      name,
      phoneNumber,
      documentType,
      picture,
    });
  };

  return (
    <div className="kycPage">
      <h2 className="heading">KYC Verification</h2>
      <input
        type="text"
        placeholder="Full Name"
        value={name}
        onChange={(e) => setName(e.target.value)}
        className="input"
      />
      <input
        type="text"
        placeholder="Phone Number"
        value={phoneNumber}
        onChange={(e) => setPhoneNumber(e.target.value)}
        className="input"
      />
      <select
        value={documentType}
        onChange={(e) => setDocumentType(e.target.value)}
        className="input"
      >
        <option value="passport">Passport</option>
        <option value="driver_license">Driver's License</option>
        <option value="ID_card">ID Card</option>
        <option value="picture">Picture</option>
      </select>
      <input
        type="file"
        onChange={(e) => setPicture(e.target.files[0])}
        className="input"
      />
      <button onClick={handleSubmit} className="button">
        Submit
      </button>
    </div>
  );
};

// App Component
const App = () => {
  return (
    <Router>
      <div className="app">
        <Routes>
          <Route path="/" element={<HomePage />} />
          <Route path="/login" element={<LoginPage />} />
          <Route path="/signup" element={<SignupPage />} />
          <Route path="/kyc" element={<KYCForm />} />
        </Routes>
      </div>
    </Router>
  );
};

export default App;
